TOLERANCE = 1e-6


# ----------------------------------------------------------------------
# printing
# ----------------------------------------------------------------------


def passed(name, detail):
    print("✅ " + name + ": " + detail)
    return True


def not_written_yet(name):
    print("⏳ " + name + " is not implemented yet. This is where you start!")
    return False


def failed(name, lines, hint):
    print("❌ " + name + ":")
    for line in lines:
        print("   " + line)
    print("   💡 " + hint)
    return False


def crashed(name, error, verbose):
    if verbose:
        traceback.print_exception(type(error), error, error.__traceback__)
    print("❌ " + name + " raised " + type(error).__name__ + ": " + str(error))
    where = student_line(error)
    if where:
        print("   " + where)
    if not verbose:
        print("   💡 Re-run this check with verbose=True for the full traceback.")
    return False


def student_line(error):
    """A short pointer to the deepest line of student code, if there is one."""
    frames = []
    for frame in traceback.extract_tb(error.__traceback__):
        if frame.filename and "lab5kit" not in frame.filename:
            frames.append(frame)
    if not frames or not frames[-1].line:
        return ""
    return "your line " + str(frames[-1].lineno) + ": " + frames[-1].line.strip()


# ----------------------------------------------------------------------
# shared fixtures
# ----------------------------------------------------------------------


def standard_maze():
    """The maze every check uses: epsilon 0.1, p_move 0.8."""
    return Maze()


def fixture_trajectory():
    """The fixed trajectory the filter checks run on.

    Rebuilt from the recorded cells, actions and readings rather than
    simulated, so it cannot drift if the random number generator changes.
    """
    recorded = EXPECTED["fixture"]
    return Trajectory(
        cells=[tuple(cell) for cell in recorded["cells"]],
        actions=list(recorded["actions"]),
        readings=[tuple(reading) for reading in recorded["readings"]],
    )


def belief_problems(world, belief, label="the belief"):
    """Everything structurally wrong with a returned belief, as message lines."""
    lines = []
    if not isinstance(belief, dict):
        return [f"{label} should be a dictionary of cell -> probability, "
                f"but it is a {type(belief).__name__}"]

    expected_keys = set(world.cells)
    keys = set(belief)
    missing = sorted(expected_keys - keys)
    extra = sorted(keys - expected_keys)
    if missing:
        lines.append(f"{label} is missing {len(missing)} free cells, "
                     f"starting with {missing[:3]}")
    if extra:
        walls = [cell for cell in extra if cell in world.walls]
        if walls:
            lines.append(f"{label} has entries for walls: {walls[:3]}. "
                         "The robot cannot be inside a wall.")
        else:
            lines.append(f"{label} has keys that are not cells of this maze: "
                         f"{extra[:3]}")
    for cell, probability in belief.items():
        if not isinstance(probability, (int, float, np.floating)):
            lines.append(f"{label}[{cell}] is a {type(probability).__name__}, "
                         "not a number")
            break
        if probability < -TOLERANCE:
            lines.append(f"{label}[{cell}] is {probability:.6f}, and a "
                         "probability cannot be negative")
            break
    return lines


def sums_to_one(belief):
    return abs(sum(belief.values()) - 1.0) <= 1e-9


def describe_model(moves):
    """A motion model's row, without the floating-point dust."""
    return ", ".join(f"{cell} {probability:.2f}"
                     for cell, probability in sorted(moves.items()))


def describe_top(belief, count=3):
    """The most likely few cells, as a readable string."""
    ordered = sorted(belief.items(), key=lambda pair: (-pair[1], pair[0]))
    return ", ".join(f"{cell} {probability:.4f}"
                     for cell, probability in ordered[:count])


# ----------------------------------------------------------------------
# Task 1: the sensor model
# ----------------------------------------------------------------------


def check_sensor_likelihood(sensor_likelihood, verbose=False):
    """Check a sensor_likelihood(world, reading, cell) implementation."""
    name = "sensor_likelihood"
    try:
        world = standard_maze()
        cell = (1, 1)
        truth = world.signature(cell)          # (1, 0, 0, 1)

        perfect = sensor_likelihood(world, truth, cell)
        if not isinstance(perfect, (int, float, np.floating)):
            return failed(
                name,
                [f"it returned a {type(perfect).__name__}, not a number"],
                "Return a single probability: the product of four factors.")
        if abs(perfect - 0.9 ** 4) > TOLERANCE:
            return failed(
                name,
                [f"in cell {cell} a perfect sonar would read {truth}.",
                 f"P({truth} | {cell}) came out as {perfect:.6f}, "
                 f"expected {0.9 ** 4:.6f}"],
                "Every beam agrees with the truth here, so every factor is "
                "1 - epsilon = 0.9, and the answer is 0.9 ** 4.")

        one_wrong = (1 - truth[0],) + tuple(truth[1:])
        got = sensor_likelihood(world, one_wrong, cell)
        want = 0.9 ** 3 * 0.1
        if abs(got - want) > TOLERANCE:
            detail = [f"the north beam of {one_wrong} disagrees with the "
                      f"truth {truth} in cell {cell}, and the other three agree.",
                      f"got {got:.6f}, expected {want:.6f}"]
            if abs(got - 0.1 ** 4) <= TOLERANCE:
                detail.append("it looks like every factor came out as epsilon: "
                              "check which way round your comparison is.")
            return failed(
                name, detail,
                "One beam lying costs a factor of epsilon; the other three "
                "telling the truth each cost 1 - epsilon.")

        all_wrong = tuple(1 - bit for bit in truth)
        got = sensor_likelihood(world, all_wrong, cell)
        if abs(got - 0.1 ** 4) > TOLERANCE:
            return failed(
                name,
                [f"with all four beams wrong, got {got:.8f}, "
                 f"expected {0.1 ** 4:.8f}"],
                "This reading is possible, just unlikely: epsilon ** 4. "
                "It must not come out as 0.")

        # The noise has to be read off the world, not written into the function.
        noisy = world.variant(epsilon=0.25)
        got = sensor_likelihood(noisy, truth, cell)
        if abs(got - 0.75 ** 4) > TOLERANCE:
            return failed(
                name,
                [f"with world.epsilon = 0.25, P({truth} | {cell}) came out as "
                 f"{got:.6f}, expected {0.75 ** 4:.6f}"],
                "Use world.epsilon rather than 0.1. Part 6 hands this "
                "function a world whose sonar noise is different.")

        # Likelihoods are not a distribution over cells and must not be
        # normalized: this total is nowhere near 1.
        reading = (1, 0, 1, 0)
        total = sum(sensor_likelihood(world, reading, c) for c in world.cells)
        if abs(total - 1.0) <= TOLERANCE:
            return failed(
                name,
                [f"adding P({reading} | cell) over all 30 cells gives exactly "
                 "1.0, which means the function is dividing by the total"],
                "This is P(reading | cell), not P(cell | reading). Each cell "
                "is answered on its own, with no reference to the others. "
                "Normalizing is update's job.")

        return passed(name, f"P({truth} | {cell}) = {perfect:.4f}, "
                            f"one beam wrong {want:.4f}, "
                            f"all four wrong {0.1 ** 4:.4f}")
    except NotImplementedError:
        return not_written_yet(name)
    except Exception as error:  # noqa: BLE001 - reported to the student
        return crashed(name, error, verbose)


