# Task 2: the motion model
# ----------------------------------------------------------------------


def check_predict(predict, verbose=False):
    """Check a predict(world, belief, action) implementation."""
    name = "predict"
    try:
        world = standard_maze()

        # From a cell the robot knows it is in, predict must reproduce the
        # motion model exactly.
        cell = (1, 1)
        got = predict(world, world.point_belief(cell), "east")
        problems = belief_problems(world, got, "predict's result")
        if problems:
            return failed(name, problems,
                          "Return a dictionary with one entry per free "
                          "cell in world.cells, including the cells whose "
                          "probability is 0.")

        want = world.transition(cell, "east")
        for landing, probability in want.items():
            if abs(got[landing] - probability) > TOLERANCE:
                lines = [
                    f"starting certain of {cell} and driving east, the motion "
                    f"model says {describe_model(want)}.",
                    f"your belief has {landing} at {got[landing]:.6f}, "
                    f"expected {probability:.6f}",
                    f"your top cells: {describe_top(got)}",
                ]
                if abs(got[world.neighbor(cell, "east")] - 1.0) < TOLERANCE:
                    lines.append(
                        "all of the probability went to the intended cell, so "
                        "the 20% that drifts sideways is missing.")
                return failed(
                    name, lines,
                    "With all the probability on one cell, the answer is just "
                    "that cell's row of the motion model. Make sure you are "
                    "spreading mass *from* each cell *to* the cells "
                    "world.transition(cell, action) names.")

        if abs(sum(got.values()) - 1.0) > 1e-9:
            return failed(
                name,
                [f"the probabilities add up to {sum(got.values()):.6f}, not 1"],
                "Every cell's transition probabilities already add to 1, so "
                "moving cannot create or destroy belief. Check you are adding "
                "to the new belief rather than overwriting it.")

        # Driving into a wall: the robot stays, and no mass enters the wall.
        got = predict(world, world.point_belief(cell), "west")
        if abs(got[cell] - 0.9) > TOLERANCE:
            return failed(
                name,
                [f"{cell} has a wall to the west and to the north, so driving "
                 "west leaves the robot where it is 0.9 of the time "
                 "(0.8 blocked, plus 0.1 of the northward drift also blocked).",
                 f"your belief puts {got[cell]:.6f} on {cell}",
                 f"your top cells: {describe_top(got)}"],
                "world.transition already handles walls. Trust what it "
                "returns instead of working out the move yourself.")

        # A uniform belief, where every cell contributes.
        got = predict(world, world.uniform_belief(), "north")
        for key, want_value in EXPECTED["predict_uniform_north"].items():
            where = tuple(int(part) for part in key.strip("()").split(","))
            if abs(got[where] - want_value) > TOLERANCE:
                return failed(
                    name,
                    ["starting from a uniform belief and driving north, "
                     f"cell {where} should hold {want_value:.6f}, "
                     f"but it holds {got[where]:.6f}",
                     f"your top cells: {describe_top(got)}"],
                    "Mass piles up against the north wall, because a blocked "
                    "move leaves the robot in place. If your numbers are all "
                    "1/30 you are not moving anything; if the whole belief "
                    "shifted bodily north, the blocked cases are missing.")

        return passed(name, "the motion model is applied in the right "
                            "direction, walls included, and the belief still "
                            "sums to 1")
    except NotImplementedError:
        return not_written_yet(name)
    except Exception as error:  # noqa: BLE001
        return crashed(name, error, verbose)


