def check_update(update, verbose=False):
    """Check an update(world, belief, reading) implementation."""
    name = "update"
    try:
        world = standard_maze()
        reading = (1, 0, 1, 0)

        got = update(world, world.uniform_belief(), reading)
        problems = belief_problems(world, got, "update's result")
        if problems:
            return failed(name, problems,
                          "Return a dictionary with one entry per free cell.")

        if abs(sum(got.values()) - 1.0) > 1e-9:
            return failed(
                name,
                [f"the probabilities add up to {sum(got.values()):.6f}, not 1",
                 f"your top cells: {describe_top(got)}"],
                "Multiplying by the likelihood leaves a set of numbers "
                "that no longer add to 1. Divide every one of them by their "
                "total, which is P(reading).")

        expected = EXPECTED["update_uniform_1010"]
        if got[expected["top"]] < max(got.values()) - TOLERANCE:
            return failed(
                name,
                [f"after reading {reading} from a uniform belief, the most "
                 f"likely cell should be {expected['top']}",
                 f"your top cells: {describe_top(got)}"],
                "The reading reports a wall to the north, a wall to the "
                "south, and open space to the east and west, which describes "
                "a corridor running from left to right. Those cells should "
                "gain probability, and every other cell should lose it.")

        for key in ("(1, 2)", "(3, 4)", "(5, 1)"):
            where = tuple(int(part) for part in key.strip("()").split(","))
            want_value = expected[key]
            if abs(got[where] - want_value) > TOLERANCE:
                lines = [f"after reading {reading} from a uniform belief, "
                         f"cell {where} should hold {want_value:.6f}, "
                         f"but it holds {got[where]:.6f}",
                         f"your top cells: {describe_top(got)}"]
                if abs(got[where] - want_value * 30) < TOLERANCE:
                    lines.append("your number is 30 times too big: the "
                                 "division is by the total, not by the "
                                 "number of cells.")
                return failed(
                    name, lines,
                    "Each cell's new probability is its old one times "
                    "P(reading | cell), all divided by the sum of those "
                    "products. If sensor_likelihood is wrong then these "
                    "numbers cannot be right either, so run its check "
                    "first.")

        # A reading cannot move the robot.
        cell = (3, 4)
        got = update(world, world.point_belief(cell), (1, 1, 1, 1))
        if abs(got[cell] - 1.0) > TOLERANCE:
            return failed(
                name,
                [f"starting certain of {cell}, a reading of (1, 1, 1, 1) is "
                 "very surprising there, but there is nowhere else for the "
                 "robot to be, so the belief must stay at 1.0.",
                 f"your belief puts {got[cell]:.6f} on {cell}",
                 f"your top cells: {describe_top(got)}"],
                "Surprise alone does not move probability between cells. If "
                "mass has moved, the motion model has crept into update.")

        # With a perfect sonar, only the cells that match survive.
        perfect = world.variant(epsilon=0.0)
        matching = perfect.matching_cells(reading)
        got = update(perfect, perfect.uniform_belief(), reading)
        share = 1.0 / len(matching)
        for place, probability in got.items():
            want_value = share if place in matching else 0.0
            if abs(probability - want_value) > TOLERANCE:
                return failed(
                    name,
                    [f"with world.epsilon = 0 the reading {reading} rules out "
                     f"every cell but {len(matching)} of them, which should "
                     f"then share the belief equally at {share:.6f} each.",
                     f"cell {place} holds {probability:.6f}, "
                     f"expected {want_value:.6f}"],
                    "Read the noise off the world rather than assuming 0.1.")

        return passed(name, f"reading {reading} from uniform puts "
                            f"{expected['top_probability']:.4f} on "
                            f"{expected['top']}, and the belief sums to 1")
    except NotImplementedError:
        return not_written_yet(name)
    except Exception as error:  # noqa: BLE001
        return crashed(name, error, verbose)


