def check_filter_sequence(filter_sequence, verbose=False):
    """Check a filter_sequence(world, belief, actions, readings) implementation."""
    name = "filter_sequence"
    try:
        world = standard_maze()
        trajectory = fixture_trajectory()
        expected = EXPECTED["filter_fixture"]

        got = filter_sequence(world, world.uniform_belief(),
                              trajectory.actions, trajectory.readings)
        if not isinstance(got, (list, tuple)):
            return failed(
                name,
                [f"it returned a {type(got).__name__}, not a list of beliefs"],
                "Collect the beliefs in a list as you go and return it.")

        if len(got) != expected["length"]:
            return failed(
                name,
                [f"it returned {len(got)} beliefs for "
                 f"{len(trajectory.actions)} actions and "
                 f"{len(trajectory.readings)} readings, "
                 f"expected {expected['length']}"],
                "One belief per reading, the first one included: the belief "
                "after reading 0 but before any action, then one after each "
                "action-and-reading pair.")

        for index, belief in enumerate(got):
            problems = belief_problems(world, belief, f"belief {index}")
            if problems:
                return failed(name, problems,
                              "Each entry should be the kind of dictionary "
                              "update returns.")
            if not sums_to_one(belief):
                return failed(
                    name,
                    [f"belief {index} adds up to {sum(belief.values()):.6f}, "
                     "not 1"],
                    "If update and predict both pass their checks, the only "
                    "way to break this is to feed one of them something it "
                    "did not expect.")

        first = got[0]
        top = max(sorted(first), key=lambda place: first[place])
        if (top != expected["first_top"]
                or abs(first[top] - expected["first_top_probability"]) > TOLERANCE):
            return failed(
                name,
                ["the first belief should be the uniform belief updated on "
                 f"reading 0 alone: {expected['first_top']} at "
                 f"{expected['first_top_probability']:.6f}.",
                 f"yours has {top} at {first[top]:.6f}",
                 f"your top cells: {describe_top(first)}"],
                "The robot takes a reading before it moves, so the run starts "
                "with an update, not a predict. Nothing has moved yet at t=0.")

        for t, (belief, want_cell, want_truth) in enumerate(
                zip(got, expected["map_cells"], expected["p_truth"])):
            best = max(sorted(belief), key=lambda place: belief[place])
            here = trajectory.cells[t]
            if abs(belief[here] - want_truth) > TOLERANCE:
                lines = []
                if best != want_cell:
                    lines.append(
                        f"at t = {t} your best guess is {best} "
                        f"({belief[best]:.4f}), but it should be {want_cell}.")
                lines += [
                    f"at t = {t} the robot is in {here}, and the belief "
                    f"should put {want_truth:.6f} there, not "
                    f"{belief[here]:.6f}.",
                    f"your top cells: {describe_top(belief)}",
                ]
                if t > 0:
                    lines.append(
                        f"everything up to t = {t - 1} was right, so look at "
                        "which action and which reading step " + str(t) +
                        " uses.")
                return failed(
                    name, lines,
                    "Each step is a predict on the action followed by an "
                    "update on the reading, in that order, with action "
                    "t - 1 paired with reading t. Performing them in the "
                    "other order, or pairing the wrong reading, goes wrong "
                    "here first.")

        return passed(name, f"{len(got)} beliefs, correct at every step; "
                            f"by t = {len(got) - 1} it puts "
                            f"{expected['p_truth'][-1]:.3f} on the truth")
    except NotImplementedError:
        return not_written_yet(name)
    except Exception as error:  # noqa: BLE001
        return crashed(name, error, verbose)


# ----------------------------------------------------------------------
# Task 5: the most likely path (second notebook)
# ----------------------------------------------------------------------


def path_log_probability(world, belief, actions, readings, path):
    """log P(this exact path and these readings), given the actions.

    The score ``viterbi_path`` is supposed to maximize. Returns -inf for a
    path the robot could not have taken, or one a reading rules out entirely.
    """
    def log(value):
        return -math.inf if value <= 0.0 else math.log(value)

    if len(path) != len(readings):
        raise ValueError(f"a path over {len(readings)} readings needs "
                         f"{len(readings)} cells, not {len(path)}")

    epsilon = world.epsilon
    def beam_likelihood(reading, cell):
        value = 1.0
        for observed, actual in zip(reading, world.signature(cell)):
            value *= (1.0 - epsilon) if observed == actual else epsilon
        return value

    total = log(belief[path[0]]) + log(beam_likelihood(readings[0], path[0]))
    for t, action in enumerate(actions):
        total += log(world.transition(path[t], action).get(path[t + 1], 0.0))
        total += log(beam_likelihood(readings[t + 1], path[t + 1]))
    return total


def check_viterbi_path(viterbi_path, verbose=False):
    """Check a viterbi_path(world, belief, actions, readings) implementation."""
    name = "viterbi_path"
    try:
        world = standard_maze()
        trajectory = fixture_trajectory()
        belief = world.uniform_belief()
        want_score = EXPECTED["viterbi_fixture"]["log_probability"]

        got = viterbi_path(world, belief, trajectory.actions,
                           trajectory.readings)
        if not isinstance(got, (list, tuple)):
            return failed(
                name,
                [f"it returned a {type(got).__name__}, not a list of cells"],
                "Return the cells of the best path, earliest first.")
        if len(got) != len(trajectory.readings):
            return failed(
                name,
                [f"it returned {len(got)} cells for "
                 f"{len(trajectory.readings)} readings"],
                "One cell per time step, the starting cell included.")

        outside = [place for place in got if tuple(place) not in set(world.cells)]
        if outside:
            return failed(
                name,
                [f"these are not free cells of the maze: {outside[:3]}"],
                "Every step of the path has to be somewhere the robot could be.")
        got = [tuple(place) for place in got]

        score = path_log_probability(world, belief, trajectory.actions,
                                     trajectory.readings, got)
        if score == -math.inf:
            broken = []
            for t in range(len(got) - 1):
                if got[t + 1] not in world.transition(got[t],
                                                      trajectory.actions[t]):
                    broken.append((t, got[t], got[t + 1]))
            lines = ["the path you returned has probability 0."]
            if broken:
                t, here, there = broken[0]
                lines.append(f"at t = {t} it goes from {here} to {there}, "
                             f"which action '{trajectory.actions[t]}' cannot do.")
                lines.append("that is what the sequence of per-step best "
                             "guesses looks like, and it is exactly what "
                             "this task is for.")
            return failed(
                name, lines,
                "The path has to hold together: each cell must be reachable "
                "from the one before it. Carry a backpointer saying which "
                "predecessor gave each cell its best score, and follow those "
                "back from the end.")

        if score < want_score - 1e-6:
            return failed(
                name,
                [f"your path scores {score:.4f}, but there is a path scoring "
                 f"{want_score:.4f}, so yours is not the most likely one.",
                 f"yours starts {got[:4]}"],
                "A path that is legal but not optimal usually means the "
                "maximum is being taken in the wrong place: at each step, "
                "each cell keeps the best score over its possible "
                "predecessors, and nothing is thrown away until the end.")
        if score > want_score + 1e-6:
            return failed(
                name,
                [f"your path scores {score:.4f}, which beats the reference "
                 f"score of {want_score:.4f}. Something is being counted "
                 "twice, or a factor is missing."],
                "Score a path by multiplying the prior on its first cell, "
                "each move's probability, and each reading's likelihood. "
                "Check against lab5kit.checks.path_log_probability.")

        return passed(name, f"a legal path scoring {score:.4f}, "
                            "which is the best there is")
    except NotImplementedError:
        return not_written_yet(name)
    except Exception as error:  # noqa: BLE001
        return crashed(name, error, verbose)


# ----------------------------------------------------------------------
# everything at once
# ----------------------------------------------------------------------


def check_all(sensor_likelihood=None, predict=None, update=None,
              filter_sequence=None, viterbi_path=None, verbose=False):
    """Run every check whose function is passed in, and summarize."""
    jobs = [
        ("sensor_likelihood", sensor_likelihood, check_sensor_likelihood),
        ("predict", predict, check_predict),
        ("update", update, check_update),
        ("filter_sequence", filter_sequence, check_filter_sequence),
        ("viterbi_path", viterbi_path, check_viterbi_path),
    ]
    results = {}
    for label, function, check in jobs:
        if function is None:
            continue
        results[label] = check(function, verbose=verbose)
    done = sum(1 for value in results.values() if value)
    print(f"\n{done} of {len(results)} checks passing.")
    return results
